import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"34、【大壮】 乾下震上","description":"横渠易说 - 34、【大壮】 乾下震上","frontmatter":{"title":"34、【大壮】 乾下震上","description":"横渠易说 - 34、【大壮】 乾下震上"},"headers":[],"relativePath":"zh/classics/hengqu/036.md","filePath":"zh/classics/hengqu/036.md"}'),l={name:"zh/classics/hengqu/036.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_34、【大壮】-乾下震上" tabindex="-1">34、【大壮】 乾下震上 <a class="header-anchor" href="#_34、【大壮】-乾下震上" aria-label="Permalink to “34、【大壮】 乾下震上”">​</a></h1><h3 id="彖曰-大壮-大者壮也-刚以动故壮。-大壮利贞-大者正也-正大而天地之情可见矣。" tabindex="-1">彖曰：大壮，大者壮也，刚以动故壮。“大壮利贞”，大者正也，正大而天地之情可见矣。 <a class="header-anchor" href="#彖曰-大壮-大者壮也-刚以动故壮。-大壮利贞-大者正也-正大而天地之情可见矣。" aria-label="Permalink to “彖曰：大壮，大者壮也，刚以动故壮。“大壮利贞”，大者正也，正大而天地之情可见矣。”">​</a></h3><h3 id="象曰-雷在天上-大壮-君子以非礼弗履。" tabindex="-1">象曰：雷在天上，大壮，君子以非礼弗履。 <a class="header-anchor" href="#象曰-雷在天上-大壮-君子以非礼弗履。" aria-label="Permalink to “象曰：雷在天上，大壮，君子以非礼弗履。”">​</a></h3><p>克己反礼，壮莫甚焉，故易于大壮见之。 克己，下学上达交相养也，下学则必达，达则必上，盖不行则终何以成德？明则诚矣，诚则明矣，克己要当以理义战退私己，盖理乃天德，克己者必有刚强壮健之德乃胜己。“雷在天上，大壮，君子以非礼弗履”。夫酒清人渴而不敢饮，肴乾人饥而不敢食，非强有力者不能人所不能。人所以不能行己者，于其所难者则惰，其异俗者虽易而羞缩。惟心弘则不顾人之非笑，所趋义理耳，视天下莫能移其道。然为之人亦未必怪，正以在己者义理不胜惰与羞缩之病，消则有长，不消则病常在，消尽则是大而化之之谓圣。意思龌龊，无由作事。在古气节之士冒死以有为，于义未必中，然非有志概者莫能。况吾于义理已明，何为不为？正以不刚。惟大壮乃能克己，盖君子欲身行之，为事业以教天下。今夫为长者折枝，非不能也，但耻以为屈而不为耳，不顾义理之若何。</p><h3 id="初九-壮于趾-征凶-有孚。-象曰-壮于趾-其孚穷也。" tabindex="-1">初九，壮于趾，征凶，有孚。 象曰：“壮于趾”，其孚穷也。 <a class="header-anchor" href="#初九-壮于趾-征凶-有孚。-象曰-壮于趾-其孚穷也。" aria-label="Permalink to “初九，壮于趾，征凶，有孚。 象曰：“壮于趾”，其孚穷也。”">​</a></h3><h3 id="九二-贞吉。-象曰-九二贞吉-以中也。" tabindex="-1">九二，贞吉。 象曰：“九二贞吉”，以中也。 <a class="header-anchor" href="#九二-贞吉。-象曰-九二贞吉-以中也。" aria-label="Permalink to “九二，贞吉。 象曰：“九二贞吉”，以中也。”">​</a></h3><h3 id="九三-小人用壮-君子用罔-贞厉。羝羊触藩-羸其角。-象曰-小人用壮-君子罔也。" tabindex="-1">九三，小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。 象曰：“小人用壮”，君子罔也。 <a class="header-anchor" href="#九三-小人用壮-君子用罔-贞厉。羝羊触藩-羸其角。-象曰-小人用壮-君子罔也。" aria-label="Permalink to “九三，小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。 象曰：“小人用壮”，君子罔也。”">​</a></h3><p>以阳居阳，正也，然乘下之刚，故危。小人用此而进，如羝羊触藩以为壮，故多见困，君子知几则否。藩以喻四、三有应，所之在进而位正理直，小人处之，必以刚动。</p><h3 id="九四-贞吉悔亡。藩决不羸-壮于大舆之輹。-象曰-藩决不羸-尚往也。" tabindex="-1">九四，贞吉悔亡。藩决不羸，壮于大舆之輹。 象曰：“藩决不羸”，尚往也。 <a class="header-anchor" href="#九四-贞吉悔亡。藩决不羸-壮于大舆之輹。-象曰-藩决不羸-尚往也。" aria-label="Permalink to “九四，贞吉悔亡。藩决不羸，壮于大舆之輹。 象曰：“藩决不羸”，尚往也。”">​</a></h3><p>乘刚本有悔，不用其壮，故贞吉。三以四为藩，九四上无阳爻，故曰藩决，壮舆之輹，往无咎也。四能不为阴累，守己以正，则吉而无乘刚之悔，且得众阳之助以销阴慝。</p><h3 id="六五-丧羊于易-无悔。-象曰-丧羊于易-位不当也。" tabindex="-1">六五，丧羊于易，无悔。 象曰：“丧羊于易”，位不当也。 <a class="header-anchor" href="#六五-丧羊于易-无悔。-象曰-丧羊于易-位不当也。" aria-label="Permalink to “六五，丧羊于易，无悔。 象曰：“丧羊于易”，位不当也。”">​</a></h3><p>羊外柔而内很，六五以阴处阳，羊丧之象也，能去其内刚，不拒来者，则无悔，故曰“丧羊于易无悔”。履柔危之地，乘壮动之刚，固之必悔者，位非其所堪也。</p><h3 id="上六-羝羊触藩-不能退-不能遂-无攸利-艰则吉。-象曰-不能退-不能遂-不详也。-艰则吉-咎不长也。" tabindex="-1">上六，羝羊触藩，不能退，不能遂，无攸利，艰则吉。 象曰：“不能退，不能遂”，不详也。“艰则吉”，咎不长也。 <a class="header-anchor" href="#上六-羝羊触藩-不能退-不能遂-无攸利-艰则吉。-象曰-不能退-不能遂-不详也。-艰则吉-咎不长也。" aria-label="Permalink to “上六，羝羊触藩，不能退，不能遂，无攸利，艰则吉。 象曰：“不能退，不能遂”，不详也。“艰则吉”，咎不长也。”">​</a></h3><p>刚竞用触则进退皆凶，危惧求全则咎有时而息也。然上六以阴居上，不详事宜，用壮而触，故进退不能。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
